#include <windows.h>
#include <stdio.h>

static DWORD g_workerId = 0;
static HANDLE g_ready = nullptr;

static DWORD WINAPI Worker(LPVOID) {
    g_workerId = GetCurrentThreadId();
    SetEvent(g_ready);
    Sleep(2000);
    return 0;
}

int main() {
    g_ready = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    HANDLE worker = CreateThread(nullptr, 0, Worker, nullptr, 0, nullptr);
    if (g_ready == nullptr || worker == nullptr) {
        return 1;
    }
    WaitForSingleObject(g_ready, 1000);

    DWORD currentId = GetCurrentThreadId();
    BOOL attached = AttachThreadInput(currentId, g_workerId, TRUE);
    printf("AttachThreadInput(attach): %s\n", attached ? "ok" : "failed");

    if (attached) {
        BOOL detached = AttachThreadInput(currentId, g_workerId, FALSE);
        printf("AttachThreadInput(detach): %s\n",
            detached ? "ok" : "failed");
    }

    WaitForSingleObject(worker, INFINITE);
    CloseHandle(worker);
    CloseHandle(g_ready);
    return 0;
}

