int main() {
    HANDLE thread = CreateThread(nullptr, 0, Worker, nullptr,
        CREATE_SUSPENDED, nullptr);
    if (thread == nullptr) {
        return 1;
    }

    CONTEXT context = {};
    context.ContextFlags = CONTEXT_CONTROL;
    if (GetThreadContext(thread, &context)) {
        // Re-applying the same context is a benign no-op.
        SetThreadContext(thread, &context);
    }

    ResumeThread(thread);
    WaitForSingleObject(thread, 5000);
    CloseHandle(thread);
    return 0;
}

