#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD FindFirstThread(DWORD processId) {
    HANDLE snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0);
    if (snapshot == INVALID_HANDLE_VALUE) {
        return 0;
    }

    THREADENTRY32 entry = { sizeof(entry) };
    DWORD threadId = 0;
    if (Thread32First(snapshot, &entry)) {
        do {
            if (entry.th32OwnerProcessID == processId) {
                threadId = entry.th32ThreadID;
                break;
            }
        } while (Thread32Next(snapshot, &entry));
    }

    CloseHandle(snapshot);
    return threadId;
}

int main() {
    wchar_t wow64Directory[MAX_PATH] = {};
    if (GetSystemWow64DirectoryW(wow64Directory, MAX_PATH) == 0) {
        printf("WOW64 is not available on this system.\n");
        return 0;
    }

    wchar_t commandLine[MAX_PATH * 2] = {};
    swprintf_s(commandLine,
        L"\"%s\\cmd.exe\" /c timeout /t 10 /nobreak > nul", wow64Directory);

    STARTUPINFOW startup = { sizeof(startup) };
    PROCESS_INFORMATION process = {};
    if (!CreateProcessW(nullptr, commandLine, nullptr, nullptr, FALSE,
            CREATE_SUSPENDED | CREATE_NO_WINDOW, nullptr, nullptr, &startup,
            &process)) {
        return 1;
    }

    DWORD threadId = FindFirstThread(process.dwProcessId);
    HANDLE thread = threadId != 0 ? OpenThread(
        THREAD_GET_CONTEXT | THREAD_SET_CONTEXT | THREAD_SUSPEND_RESUME,
        FALSE, threadId) : nullptr;

    if (thread != nullptr) {
        WOW64_CONTEXT context = {};
        context.ContextFlags = WOW64_CONTEXT_CONTROL;
        if (Wow64GetThreadContext(thread, &context)) {
            BOOL updated = Wow64SetThreadContext(thread, &context);
            printf("Wow64SetThreadContext: %s\n",
                updated ? "ok" : "failed");
        } else {
            printf("Wow64GetThreadContext failed: %lu\n", GetLastError());
        }
        CloseHandle(thread);
    } else {
        printf("Could not open the WOW64 thread: %lu\n", GetLastError());
    }

    TerminateProcess(process.hProcess, 0);
    WaitForSingleObject(process.hProcess, 1000);
    CloseHandle(process.hThread);
    CloseHandle(process.hProcess);
    return 0;
}
